// Check if current time is within work hours (8 AM - 6 PM)
const now = new Date();
const vietnamTime = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));
const hour = vietnamTime.getHours();

const isWorkHours = hour >= 8 && hour <= 18;

return [{
  json: {
    is_work_hours: isWorkHours,
    current_hour: hour,
    check_time: vietnamTime.toISOString(),
    timezone: 'Asia/Ho_Chi_Minh',
    one_hour_ago: new Date(vietnamTime.getTime() - 3600000).toISOString()
  }
}];

// Mock data: Get meetings from Google Calendar
// TODO: Thay thế bằng Google Calendar node thật
// Google Calendar API: GET https://www.googleapis.com/calendar/v3/calendars/primary/events

const now = new Date();
const oneHourAgo = new Date(now.getTime() - 3600000);

// Mock meetings - thay thế bằng data từ Google Calendar API
const completedMeetings = [
  {
    id: 'meeting_001',
    summary: 'Team Standup',
    attendees: ['user@company.com', 'teammate@company.com'],
    start: oneHourAgo.toISOString(),
    end: new Date(oneHourAgo.getTime() + 1800000).toISOString(),
    has_recording: false,
    recording_url: '',
    conference_data: null
  }
];

console.log(`Found ${completedMeetings.length} recently completed meetings`);

return completedMeetings.map(meeting => ({
  json: {
    ...meeting,
    check_time: now.toISOString()
  }
}));

