// Format meeting notes email
const meeting = $input.all().find(m => m.json.id)?.json || {};
const summary = $('Summarize Meeting (OpenAI GPT)').first()?.json?.choices?.[0]?.message?.content || 'Không có tóm tắt';

const email = {
  to: meeting.attendees?.join(', ') || '',
  subject: `📝 Meeting Notes: ${meeting.summary || 'Cuộc họp'}`,
  body: `Kính gửi mọi người,

Đây là tóm tắt cuộc họp vừa kết thúc:

━━━━━━━━━━━━━━━━━━━━
📋 ${meeting.summary || 'Cuộc họp'}
━━━━━━━━━━━━━━━━━━━━

⏰ Thời gian: ${new Date(meeting.start).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}
👥 Người tham dự: ${meeting.attendees?.join(', ') || 'N/A'}

━━━━━━━━━━━━━━━━━━━━
📝 TÓM TẮT
━━━━━━━━━━━━━━━━━━━━

${summary}

━━━━━━━━━━━━━━━━━━━━

Trân trọng,
AI Meeting Assistant`,
  meeting_id: meeting.id,
  summary_text: summary
};

return [{ json: email }];
